const $=id=>document.getElementById(id);let lang='ka';try{lang=localStorage.getItem('playerone-lang')||'ka'}catch{}if(!T[lang])lang='ka';
function setLang(l){lang=l;document.documentElement.lang=l;document.querySelectorAll('[data-t]').forEach(e=>e.innerHTML=T[l][e.dataset.t]);document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===l);b.setAttribute('aria-pressed',String(b.dataset.lang===l))});$('result').hidden=true;$('error').textContent='';try{localStorage.setItem('playerone-lang',l)}catch{}}
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>setLang(b.dataset.lang));document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{$('game').value=b.dataset.game;$('booking').scrollIntoView({behavior:'smooth'});$('game').focus({preventScroll:true})});
const localDate=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tbilisi',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);$('date').min=localDate(new Date());$('date').value=localDate(new Date());$('hours').onchange=()=>{$('estimate').textContent=Number($('hours').value)*10+' ₾';$('result').hidden=true};$('bookingForm').addEventListener('input',()=>{$('result').hidden=true;$('error').textContent=''});
$('bookingForm').onsubmit=e=>{e.preventDefault();const t=T[lang],when=new Date($('date').value+'T'+$('time').value+':00+04:00');if(!Number.isFinite(+when)||when<=new Date()){$('error').textContent=t.past;return}$('error').textContent='';$('summary').value=['PLAYER ONE · '+t.request,t.name+': '+$('name').value.trim(),t.game+': '+$('game').value,t.date+': '+$('date').value,t.time+': '+$('time').value,t.duration+': '+$('hours').value,t.players+': '+$('players').value,t.total+': '+Number($('hours').value)*10+' GEL',t.requestNote].join('\n');$('result').hidden=false;$('copyStatus').textContent='';$('result').scrollIntoView({behavior:'smooth',block:'nearest'})};$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('summary').value);$('copyStatus').textContent=T[lang].copied}catch{$('summary').select();$('copyStatus').textContent=T[lang].copyFail}};setLang(lang);
